begin;
set local statement_timeout='25s';
create temp table last_fixture_results(test text,passed boolean) on commit drop;
grant insert,select on last_fixture_results to authenticated,anon;
do $$
declare
 c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid();
 a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); pa uuid; pb uuid;
 v uuid; w uuid; f uuid; g uuid; h uuid; s uuid; t uuid; u uuid;
 denied boolean; n bigint; baseline bigint; ct uuid; pt uuid; dt uuid; r uuid; r2 uuid; rh uuid; rg uuid; ml uuid; mdl uuid; created uuid; j jsonb;
begin
 if exists(select 1 from cron.job where active) then raise exception 'Disable cron before test'; end if;
 select count(*) into baseline from public.notification_queue;
 insert into public.clubs(id,name) values(c,'ROLLBACK publication own'),(d,'ROLLBACK publication foreign');
 insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data) values
 (a,a::text||'@example.invalid','{"display_name":"Publication admin"}','{}'),
 (b,b::text||'@example.invalid','{"display_name":"Publication foreign reserve"}','{}');
 select id into pa from public.member_profiles where user_id=a;
 select id into pb from public.member_profiles where user_id=b;
 insert into public.club_memberships(club_id,member_profile_id,role,is_active) values(c,pa,'admin',true),(d,pb,'member',true);
 insert into public.venues(club_id,name,is_home_venue) values(c,'Rollback own venue',false) returning id into v;
 insert into public.venues(club_id,name,is_home_venue) values(d,'Rollback foreign venue',false) returning id into w;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(c,now()+interval '30 days',false,v,1,4) returning id into f;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(c,now()+interval '31 days',false,v,1,4) returning id into h;
 insert into public.fixtures(club_id,start_at,is_home,venue_id,rinks_required,players_per_rink) values(d,now()+interval '32 days',false,w,1,4) returning id into g;
 insert into public.team_selections(fixture_id) values(f) returning id into s;
 insert into public.team_selections(fixture_id) values(g) returning id into t;
 insert into public.team_selections(fixture_id) values(h) returning id into u;
 insert into public.team_selection_members(team_selection_id,member_profile_id,role,is_selected) values(s,pa,'reserve',true),(t,pb,'reserve',true);
 insert into public.competition_types(club_id,name,section,uses_rinks,is_internal) values(c,'Rollback repeat type','mixed',false,true) returning id into ct;
 insert into public.competition_types(club_id,name,section,uses_rinks,is_internal,selection_mode,team_selection_enabled) values(c,'Rollback preselect type','mixed',true,true,'preselect',true) returning id into pt;
 insert into public.competition_types(club_id,name,section,uses_rinks,is_internal,selection_mode,team_selection_enabled) values(d,'Rollback foreign preselect','mixed',true,true,'preselect',true) returning id into dt;
 update public.fixtures set competition_type_id=ct where id=f;
 update public.fixtures set competition_type_id=pt where id=h;
 update public.fixtures set competition_type_id=dt where id=g;
 update public.team_selections set status='published' where id in(s,u,t);
 insert into public.fixture_rinks(fixture_id,fixture_rink_no,format,players_per_rink,home_rink_label) values(f,1,'rinks',4,'A') returning id into r;
 insert into public.fixture_rinks(fixture_id,fixture_rink_no,format,players_per_rink,home_rink_label) values(f,2,'rinks',4,'B') returning id into r2;
 insert into public.fixture_rinks(fixture_id,fixture_rink_no,format,players_per_rink) values(h,1,'rinks',4) returning id into rh;
 insert into public.fixture_rinks(fixture_id,fixture_rink_no,format,players_per_rink,home_rink_label) values(g,1,'rinks',4,'C') returning id into rg;
 insert into public.mailing_lists(club_id,name) values(c,'Rollback markers') returning id into ml;
 insert into public.mailing_lists(club_id,name) values(d,'Rollback foreign markers') returning id into mdl;
 insert into public.volunteer_tasks(club_id,task_code,name,mailing_list_id) values(c,'marker','Marker',ml),(d,'marker','Marker',mdl);
 reset role; update public.club_memberships set role='member',is_active=true where club_id=c and member_profile_id=pa; update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.confirm_team_changes(s,0,'[]','[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to manage this fixture.'; end; insert into last_fixture_results values('confirm_team_changes member denied',denied);
 denied:=false; begin perform public.create_repeated_fixture_from_source(f,now()+interval '70 days',now()+interval '70 days 2 hours'); exception when raise_exception then denied:=sqlerrm='Only a club Admin or app Superuser can repeat an existing fixture.'; end; insert into last_fixture_results values('create_repeated_fixture_from_source member denied',denied);
 denied:=false; begin perform public.manage_fixture_team_structure(f,'add',p_format=>'pairs'); exception when raise_exception then denied:=sqlerrm='You do not have permission to change the team structure.'; end; insert into last_fixture_results values('manage_fixture_team_structure member denied',denied);
 denied:=false; begin perform public.swap_fixture_rink_labels(r,r2); exception when raise_exception then denied:=sqlerrm='You do not have permission to move these rink bookings.'; end; insert into last_fixture_results values('swap_fixture_rink_labels member denied',denied);
 denied:=false; begin perform public.save_preselect_fixture_state(h,'[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to maintain this fixture.'; end; insert into last_fixture_results values('save_preselect_fixture_state member denied',denied);
 denied:=false; begin perform public.repair_preselect_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to repair this fixture''s communications.'; end; insert into last_fixture_results values('repair_preselect_communications member denied',denied);
 denied:=false; begin perform public.queue_open_marker_request_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to send marker requests for this fixture.'; end; insert into last_fixture_results values('queue_open_marker_request_communications member denied',denied);
 reset role; update public.club_memberships set role='guest',is_active=true where club_id=c and member_profile_id=pa; update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.confirm_team_changes(s,0,'[]','[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to manage this fixture.'; end; insert into last_fixture_results values('confirm_team_changes guest denied',denied);
 denied:=false; begin perform public.create_repeated_fixture_from_source(f,now()+interval '70 days',now()+interval '70 days 2 hours'); exception when raise_exception then denied:=sqlerrm='Only a club Admin or app Superuser can repeat an existing fixture.'; end; insert into last_fixture_results values('create_repeated_fixture_from_source guest denied',denied);
 denied:=false; begin perform public.manage_fixture_team_structure(f,'add',p_format=>'pairs'); exception when raise_exception then denied:=sqlerrm='You do not have permission to change the team structure.'; end; insert into last_fixture_results values('manage_fixture_team_structure guest denied',denied);
 denied:=false; begin perform public.swap_fixture_rink_labels(r,r2); exception when raise_exception then denied:=sqlerrm='You do not have permission to move these rink bookings.'; end; insert into last_fixture_results values('swap_fixture_rink_labels guest denied',denied);
 denied:=false; begin perform public.save_preselect_fixture_state(h,'[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to maintain this fixture.'; end; insert into last_fixture_results values('save_preselect_fixture_state guest denied',denied);
 denied:=false; begin perform public.repair_preselect_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to repair this fixture''s communications.'; end; insert into last_fixture_results values('repair_preselect_communications guest denied',denied);
 denied:=false; begin perform public.queue_open_marker_request_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to send marker requests for this fixture.'; end; insert into last_fixture_results values('queue_open_marker_request_communications guest denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=false where club_id=c and member_profile_id=pa; update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.confirm_team_changes(s,0,'[]','[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to manage this fixture.'; end; insert into last_fixture_results values('confirm_team_changes inactive admin denied',denied);
 denied:=false; begin perform public.create_repeated_fixture_from_source(f,now()+interval '70 days',now()+interval '70 days 2 hours'); exception when raise_exception then denied:=sqlerrm='Only a club Admin or app Superuser can repeat an existing fixture.'; end; insert into last_fixture_results values('create_repeated_fixture_from_source inactive admin denied',denied);
 denied:=false; begin perform public.manage_fixture_team_structure(f,'add',p_format=>'pairs'); exception when raise_exception then denied:=sqlerrm='You do not have permission to change the team structure.'; end; insert into last_fixture_results values('manage_fixture_team_structure inactive admin denied',denied);
 denied:=false; begin perform public.swap_fixture_rink_labels(r,r2); exception when raise_exception then denied:=sqlerrm='You do not have permission to move these rink bookings.'; end; insert into last_fixture_results values('swap_fixture_rink_labels inactive admin denied',denied);
 denied:=false; begin perform public.save_preselect_fixture_state(h,'[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to maintain this fixture.'; end; insert into last_fixture_results values('save_preselect_fixture_state inactive admin denied',denied);
 denied:=false; begin perform public.repair_preselect_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to repair this fixture''s communications.'; end; insert into last_fixture_results values('repair_preselect_communications inactive admin denied',denied);
 denied:=false; begin perform public.queue_open_marker_request_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to send marker requests for this fixture.'; end; insert into last_fixture_results values('queue_open_marker_request_communications inactive admin denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa; update public.club_memberships set role='admin' where club_id=d and member_profile_id=pb;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.confirm_team_changes(s,0,'[]','[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to manage this fixture.'; end; insert into last_fixture_results values('confirm_team_changes foreign admin denied',denied);
 denied:=false; begin perform public.create_repeated_fixture_from_source(f,now()+interval '70 days',now()+interval '70 days 2 hours'); exception when raise_exception then denied:=sqlerrm='Only a club Admin or app Superuser can repeat an existing fixture.'; end; insert into last_fixture_results values('create_repeated_fixture_from_source foreign admin denied',denied);
 denied:=false; begin perform public.manage_fixture_team_structure(f,'add',p_format=>'pairs'); exception when raise_exception then denied:=sqlerrm='You do not have permission to change the team structure.'; end; insert into last_fixture_results values('manage_fixture_team_structure foreign admin denied',denied);
 denied:=false; begin perform public.swap_fixture_rink_labels(r,r2); exception when raise_exception then denied:=sqlerrm='You do not have permission to move these rink bookings.'; end; insert into last_fixture_results values('swap_fixture_rink_labels foreign admin denied',denied);
 denied:=false; begin perform public.save_preselect_fixture_state(h,'[]'); exception when raise_exception then denied:=sqlerrm='You do not have permission to maintain this fixture.'; end; insert into last_fixture_results values('save_preselect_fixture_state foreign admin denied',denied);
 denied:=false; begin perform public.repair_preselect_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to repair this fixture''s communications.'; end; insert into last_fixture_results values('repair_preselect_communications foreign admin denied',denied);
 denied:=false; begin perform public.queue_open_marker_request_communications(h); exception when raise_exception then denied:=sqlerrm='You do not have permission to send marker requests for this fixture.'; end; insert into last_fixture_results values('queue_open_marker_request_communications foreign admin denied',denied);
 reset role; update public.club_memberships set role='admin',is_active=true where club_id=c and member_profile_id=pa;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true); set local role authenticated;
 denied:=false; begin perform public.swap_fixture_rink_labels(r,rg); exception when raise_exception then denied:=sqlerrm='You do not have permission to move these rink bookings.'; end; insert into last_fixture_results values('swap validates both fixtures',denied);
 perform public.swap_fixture_rink_labels(r,r2);
 reset role; insert into last_fixture_results select 'own swap applies labels',home_rink_label='B' from public.fixture_rinks where id=r; set local role authenticated;
 created:=public.create_repeated_fixture_from_source(f,now()+interval '70 days',now()+interval '70 days 2 hours');
 reset role; insert into last_fixture_results select 'repeat retains club and creator',club_id=c and created_by_user_id=a from public.fixtures where id=created; set local role authenticated;
 j:=public.manage_fixture_team_structure(f,'add',p_format=>'pairs');
 created:=(j->>'fixture_rink_id')::uuid;
 reset role; insert into last_fixture_results select 'structure add scoped to own fixture',fixture_id=f and players_per_rink=2 from public.fixture_rinks where id=created; set local role authenticated;
 perform public.manage_fixture_team_structure(f,'delete',created);
 reset role; insert into last_fixture_results select 'structure delete removes own rink',not exists(select 1 from public.fixture_rinks where id=created); set local role authenticated;
 denied:=false; begin perform public.manage_fixture_team_structure(f,'delete',rg); exception when raise_exception then denied:=sqlerrm='The selected team was not found.'; end; insert into last_fixture_results values('structure foreign rink rejected',denied);
 denied:=false; begin perform public.confirm_team_changes(s,0,jsonb_build_array(jsonb_build_object('member_profile_id',pb,'role','player','is_selected',true)),'[]'); exception when raise_exception then denied:=sqlerrm='Target member is not an active non-Guest member of this club'; end; insert into last_fixture_results values('confirm foreign member rejected',denied);
 j:=public.confirm_team_changes(s,0,jsonb_build_array(jsonb_build_object('member_profile_id',pa,'role','player','is_selected',true)),jsonb_build_array(jsonb_build_object('fixture_rink_id',r,'position',1,'member_profile_id',pa)));
 reset role; insert into last_fixture_results select 'confirm places eligible own player',count(*)=1 from public.fixture_rink_assignments where fixture_id=f and fixture_rink_id=r and member_profile_id=pa; set local role authenticated;
 denied:=false; begin perform public.save_preselect_fixture_state(h,jsonb_build_array(jsonb_build_object('fixture_rink_id',rg,'position',1,'member_profile_id',pa))); exception when raise_exception then denied:=sqlerrm='An assignment refers to an invalid fixture rink.'; end; insert into last_fixture_results values('preselect foreign rink rejected',denied);
 denied:=false; begin perform public.save_preselect_fixture_state(h,jsonb_build_array(jsonb_build_object('fixture_rink_id',rh,'position',1,'member_profile_id',pb))); exception when raise_exception then denied:=sqlerrm='One or more selected people are not active non-Guest members of this club.'; end; insert into last_fixture_results values('preselect foreign member rejected',denied);
 j:=public.save_preselect_fixture_state(h,jsonb_build_array(jsonb_build_object('fixture_rink_id',rh,'position',1,'member_profile_id',pa)));
 insert into last_fixture_results values('preselect saves eligible own player',(j->>'assignment_count')::integer=1);
 j:=public.repair_preselect_communications(h);
 insert into last_fixture_results values('repair own fixture succeeds',j->>'fixture_id'=h::text);
 j:=public.queue_open_marker_request_communications(h);
 insert into last_fixture_results values('marker request own fixture succeeds',j is not null);
 reset role;
 perform set_config('request.jwt.claims','{}',true); set local role anon;
 denied:=false; begin perform public.confirm_team_changes(s,0,'[]','[]'); exception when insufficient_privilege then denied:=true; end; insert into last_fixture_results values('confirm_team_changes anonymous denied',denied);
 denied:=false; begin perform public.create_repeated_fixture_from_source(f,now()+interval '70 days',now()+interval '70 days 2 hours'); exception when insufficient_privilege then denied:=true; end; insert into last_fixture_results values('create_repeated_fixture_from_source anonymous denied',denied);
 denied:=false; begin perform public.manage_fixture_team_structure(f,'add',p_format=>'pairs'); exception when insufficient_privilege then denied:=true; end; insert into last_fixture_results values('manage_fixture_team_structure anonymous denied',denied);
 denied:=false; begin perform public.swap_fixture_rink_labels(r,r2); exception when insufficient_privilege then denied:=true; end; insert into last_fixture_results values('swap_fixture_rink_labels anonymous denied',denied);
 denied:=false; begin perform public.save_preselect_fixture_state(h,'[]'); exception when insufficient_privilege then denied:=true; end; insert into last_fixture_results values('save_preselect_fixture_state anonymous denied',denied);
 denied:=false; begin perform public.repair_preselect_communications(h); exception when raise_exception then denied:=sqlerrm='You must be signed in.'; end; insert into last_fixture_results values('repair_preselect_communications anonymous denied',denied);
 denied:=false; begin perform public.queue_open_marker_request_communications(h); exception when raise_exception then denied:=sqlerrm='You must be signed in.'; end; insert into last_fixture_results values('queue_open_marker_request_communications anonymous denied',denied);
 reset role;
 insert into last_fixture_results values('cron remains disabled',not exists(select 1 from cron.job where active));
 if exists(select 1 from last_fixture_results where not passed) then raise exception 'Remaining fixture checks failed'; end if;
end $$;
select * from last_fixture_results order by test;
rollback;
